package org.xmlpull.v1;
import java.io.*;
public interface XmlSerializer { void setFeature(String name,boolean value); boolean getFeature(String name); void setProperty(String name,Object value); Object getProperty(String name); void setOutput(OutputStream stream,String encoding)throws IOException; void setOutput(Writer writer)throws IOException; void startDocument(String encoding,Boolean standalone)throws IOException; void endDocument()throws IOException; void setPrefix(String prefix,String namespace)throws IOException; String getPrefix(String namespace,boolean generate); int getDepth(); String getNamespace(); String getName(); XmlSerializer startTag(String namespace,String name)throws IOException; XmlSerializer attribute(String namespace,String name,String value)throws IOException; XmlSerializer endTag(String namespace,String name)throws IOException; XmlSerializer text(String text)throws IOException; XmlSerializer text(char[] text,int start,int len)throws IOException; void cdsect(String text)throws IOException; void entityRef(String text)throws IOException; void processingInstruction(String text)throws IOException; void comment(String text)throws IOException; void docdecl(String text)throws IOException; void ignorableWhitespace(String text)throws IOException; void flush()throws IOException; }
